pub fn prompt(side: Side, files: &Files) -> String {
    use crate::baked_prompts::{divergence, fill};
    let list = |paths: &[String]| paths.join("\n");
    let intro = fill(
        divergence::INTRO,
        &[
            ("codeRoot", &files.code_root),
            ("specRoot", &files.spec_root),
        ],
    );
