        Side::Source => (
            divergence::code::TASK,
                    editor.apply_lsp_edits(&imports, window, cx)
                });
            }
        }
        // The editor drops its diagnostics on every edit.
        self.show_diagnostics(cx);
        cx.notify();
    }

